#include <iostream>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    string line;
    getline(cin, line); // Consome o '\n' restante da linha que continha N

    int balance = 0;
    bool ok = true;

    for (int i = 0; i < n; ++i) {
        getline(cin, line);
        if (!ok) continue;
        for (char c : line) {
            if (c == '{') {
                balance++;
            } else if (c == '}') {
                balance--;
                if (balance < 0) {
                    ok = false;
                }
            }
        }
    }

    if (ok && balance == 0) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
